// ================================================================
//  CONFIG
//
//  Option lists and question types are fetched live from Fillout by
//  the previous node, so nothing here needs changing when you add a
//  question, reword an option, or enable "Other".
//
//  "Other" behaviour: whatever the applicant types goes into the main
//  Folk field verbatim. Answers that DO match a real Fillout option are
//  written using Fillout's exact label, which strips stray whitespace
//  and normalises quote characters. There is no companion field.
//
//  Note: free text therefore creates a new option on the Folk select,
//  because Folk adds any value it has not seen before. Expect those
//  fields to accumulate one-off options over time.
// ================================================================

const FOLK_GROUP_ID = 'grp_411ea0ed-822d-4de9-80de-1a0512da709e';   // Pipeline (new)

// Blank = auto-detect by label. Set a Fillout question ID to override.
const CORE = { firstName: '', lastName: '', email: '', phone: '' };

// Never sent to Folk.
const SKIP = [
  'Source',      // Fillout tracking object, not an answer
  'Referral',    // no Folk field by design
  'ref',         // no Folk field by design
];

// Fillout question label  ->  Folk field name. Only where they differ.
const RENAME = {
  'Which country do you live in?': 'Country',
  'Do you have a specific business idea already, or do you need help with ideation?': 'Do you have a business idea?',
  "What's your area of expertise?": 'Area of expertise',
  'How many years of work experience do you have?': 'Years of work experience',
  'Are you Technical or Non-Technical?': 'Technical or Non-Technical',
  'Do you have experience in any of these areas?': 'GTM experience',
  'Tell us about your idea and why you think it will work': 'Idea',
  'Do you already know someone in your own network that you think might pay for this?': 'Do you know someone in your network that will pay for this?',
  'What type of business is it?': 'Type of business',
  'Is the MVP already built?': 'Is the MVP built?',
  'Please link to your MVP': 'MVP',
  'Your website': 'Website URL',
  'Who created your website?': 'Who built the website?',
  'Is your business already generating revenue?': 'Is your business generating revenue?',
  'How much revenue did it make last month (or a rolling average of the last 3 months)?': 'Revenue last month',
  "What is the total revenue you've generated over this business' lifetime?": "Total revenue over the business' lifetime",
  'What is your revenue model?': 'Revenue model',
  'How many paying customers did it have last month?': 'Number of paying customers last month',
  'How many customers have paid more than one time (renewed or expanded)?': 'Number of customers that paid more than once',
  'Do you already have a way of winning paying customers that has worked more than once?': 'Do you have a way of winning paying customers that worked more than once?',
  'Why does now feel like the right time for you to do this?': 'Why now?',
  'Are you prepared to invest USD $2k into starting your own business?': 'Are you prepared to invest USD $2k into this?',
  "We don't take equity upfront. Instead we charge $2k for a 1 month deep dive into the business to identify growth opportunities.": 'Are you prepared to invest USD $2k into this?',
  'Which option do you want to move forwards with?': 'Which DQ Ideate option are you choosing?',
};

// Collapse verbose option labels into short Folk values.
// Keyed by FOLK field name, so both branch questions share one entry.
const VALUE_MAP = {
  'Are you prepared to invest USD $2k into this?': {
    "Yes - I'm able to invest $2k into starting my own business": 'Yes',
    "Yes - I'm able to invest $2k into consulting from DQventures": 'Yes',
    "No - i'm not ready for help from DQventures yet": 'No',
  },
};

const VALUE_FALLBACK = [
  { starts: 'yes', use: 'Yes' },
  { starts: 'no',  use: 'No'  },
];

// Written on create AND update. Status resets on every submission
// (overridden to Closed-lost further down when the $2k answer is No).
const ALWAYS = {
  'Status': () => 'Applied',
  'Fillout ID': (i) => i.json.submissionId,
  'Date of Official Application': (i) => String(i.json.submissionTime || '').slice(0, 10),
};

// Note layout. Empty sections are omitted. Any question not listed here
// still appears, under "Other" at the end.
const SECTIONS = [
  { title: 'About them', fields: [
    'Which country do you live in?',
    "What's your area of expertise?",
    'How many years of work experience do you have?',
    'Are you Technical or Non-Technical?',
    'Do you have experience in any of these areas?',
  ]},
  { title: 'Where they are at', fields: [
    'Where are you at right now?',
    'Do you have a specific business idea already, or do you need help with ideation?',
  ]},
  { title: 'The idea', fields: [
    'Tell us about your idea and why you think it will work',
    'Do you already know someone in your own network that you think might pay for this?',
  ]},
  { title: 'The business', fields: [
    'What type of business is it?',
    'Is the MVP already built?',
    'Who built / is building the MVP?',
    'Please link to your MVP',
    'Do you have a website yet?',
    'Your website',
    'Who created your website?',
  ]},
  { title: 'Traction', fields: [
    'Is your business already generating revenue?',
    'How much revenue did it make last month (or a rolling average of the last 3 months)?',
    "What is the total revenue you've generated over this business' lifetime?",
    'How long ago did you launch this business?',
    'What is your revenue model?',
    'How many paying customers did it have last month?',
    'How many customers have paid more than one time (renewed or expanded)?',
    'How did your business win the existing paying customers?',
    'Do you already have a way of winning paying customers that has worked more than once?',
  ]},
  { title: 'Motivation', fields: [
    'Why do you want to start your own business?',
    'Why did you start this business?',
    'Why does now feel like the right time for you to do this?',
    'Why do you want help from DQventures?',
  ]},
  { title: 'Commitment', fields: [
    'Are you prepared to invest USD $2k into starting your own business?',
    "We don't take equity upfront. Instead we charge $2k for a 1 month deep dive into the business to identify growth opportunities.",
    'Which option do you want to move forwards with?',
  ]},
  { title: 'Source', fields: [
    'How did you hear about DQventures?',
  ]},
];

// Every custom field that exists in Pipeline (new). A question whose
// target is not on this list is reported in _warnings and included in
// the note, but never sent to Folk - so adding a question to the form
// cannot break the write for the whole submission.
const FOLK_FIELDS = [
  'Date of Official Application','Area of expertise','Idea','LinkedIn : Headline','Interview Date',
  'Why do you want to start your own business?','Why do you want help from DQventures?','Status',
  'Date of LinkedIn Application','Country','Do you have a business idea?','Years of work experience',
  'Technical or Non-Technical','GTM experience','Why now?',
  'Do you know someone in your network that will pay for this?','Type of business',
  'Is the MVP built?','MVP','Do you have a website yet?','Website URL',
  'Who built the website?','Is your business generating revenue?','Revenue last month',
  "Total revenue over the business' lifetime",'How long ago did you launch this business?','Revenue model',
  'Number of paying customers last month','Number of customers that paid more than once',
  'How did your business win the existing paying customers?',
  'Do you have a way of winning paying customers that worked more than once?','Why did you start this business?',
  'Are you prepared to invest USD $2k into this?','Lead Score','Which DQ Ideate option are you choosing?',
  'Who built / is building the MVP?','How did you hear about DQventures?','Where are you at right now?',
  'Fillout ID','Time of withdrawal','Reason for withdrawal',
];

const BRANCH_QUESTION = 'Where are you at right now?';
const ADD_GROUP_ON_UPDATE = false;

// ================================================================
//  Below here: no configuration.
// ================================================================

const norm = (s) => String(s == null ? '' : s)
  .replace(/[‘’ʼ]/g, "'")
  .replace(/[“”]/g, '"')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const asText = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join(', ');
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v).trim();
};

const asList = (v) => {
  if (v === null || v === undefined) return [];
  if (Array.isArray(v)) return v.map(asText).filter(Boolean);
  const t = asText(v);
  return t ? [t] : [];
};

// This node sits AFTER the schema fetch, so $input is the form
// definition. Submissions come from the trigger explicitly.
const submissions = $('New Application Submitted').all();

// Live form definition: authoritative option list and type for every
// question. Used to detect single vs multi select, and to write the
// exact Fillout label for answers that match a real option.
const schema = $('Fetch Form Definition').first().json || {};
const META = {};
for (const q of (schema.questions || [])) {
  const opts = Array.isArray(q.options) ? q.options : [];
  META[norm(q.name)] = {
    multi: q.type === 'Checkboxes',
    options: opts.length
      ? new Map(opts.map(o => {
          const label = String(o.label != null ? o.label : o.value).trim();
          return [norm(label), label];
        }))
      : null,
  };
}

const FIELD_SET = new Set(FOLK_FIELDS.map(norm));
const SKIP_SET  = new Set(SKIP.map(norm));

const VALUE_LOOKUP = {};
for (const [field, pairs] of Object.entries(VALUE_MAP)) {
  VALUE_LOOKUP[field] = {};
  for (const [from, to] of Object.entries(pairs)) VALUE_LOOKUP[field][norm(from)] = to;
}

const out = [];

for (const item of submissions) {
  const questions = item.json.questions || {};
  const params    = item.json.urlParameters || {};
  const warnings  = [];

  if (!schema.questions) {
    warnings.push('Form definition unavailable - option labels not normalised for this run');
  }

  const lookup = (patterns) => {
    for (const [id, q] of Object.entries(questions)) {
      const label = norm(q.name);
      if (patterns.some(p => label.includes(p))) return { id: id, raw: q.value };
    }
    for (const [k, v] of Object.entries(params)) {
      if (patterns.some(p => norm(k).includes(p))) return { id: null, raw: v };
    }
    return { id: null, raw: '' };
  };

  const takeCore = (explicitId, patterns) => {
    if (explicitId && questions[explicitId]) {
      return { id: explicitId, value: asText(questions[explicitId].value) };
    }
    const hit = lookup(patterns);
    return { id: hit.id, value: asText(hit.raw) };
  };

  const first = takeCore(CORE.firstName, ['first name']);
  const last  = takeCore(CORE.lastName,  ['last name', 'surname']);
  const mail  = takeCore(CORE.email,     ['email']);
  const tel   = takeCore(CORE.phone,     ['phone', 'mobile']);

  const coreIds = new Set([first.id, last.id, mail.id, tel.id].filter(Boolean));

  const fields   = {};
  const answers  = {};
  let   branch   = '';

  const put = (target, value) => {
    if (!FIELD_SET.has(norm(target))) {
      warnings.push('No Folk field named "' + target + '" - not written');
      return;
    }
    fields[target] = value;
  };

  for (const [id, q] of Object.entries(questions)) {
    if (coreIds.has(id)) continue;
    const label = String(q.name || '').trim();
    if (!label || SKIP_SET.has(norm(label))) continue;

    const display = asText(q.value);
    if (!display) continue;
    if (norm(label) === norm(BRANCH_QUESTION)) branch = display;
    answers[label] = display;

    const target = RENAME[label] || label;
    const meta   = META[norm(label)] || { multi: Array.isArray(q.value), options: null };

    // Deliberate relabelling wins over everything else.
    if (VALUE_LOOKUP[target]) {
      let mapped = VALUE_LOOKUP[target][norm(display)];
      if (!mapped) {
        const hit = VALUE_FALLBACK.find(f => norm(display).startsWith(norm(f.starts)));
        mapped = hit && hit.use;
      }
      if (mapped) {
        put(target, mapped);
      } else {
        warnings.push('Unmapped value for "' + target + '": "' + display + '" - not written');
      }
      continue;
    }

    // Select questions: use Fillout's exact label where the answer
    // matches a real option, otherwise pass the applicant's own words
    // through unchanged.
    if (meta.options) {
      if (meta.multi) {
        const seen = new Set();
        const values = [];
        for (const raw of asList(q.value)) {
          const write = meta.options.get(norm(raw)) || raw.trim();
          if (write && !seen.has(norm(write))) {
            seen.add(norm(write));
            values.push(write);
          }
        }
        put(target, values);
      } else {
        put(target, meta.options.get(norm(display)) || display);
      }
      continue;
    }

    put(target, meta.multi ? asList(q.value) : display);
  }

  for (const [target, fn] of Object.entries(ALWAYS)) {
    const v = asText(fn(item));
    if (v) put(target, v);
  }

  // Applicants who answer "No" to the $2k investment question (either
  // conditional variant - both map to the same Folk field via RENAME +
  // VALUE_MAP) have withdrawn within the application. Override the
  // default "Applied" status and record the withdrawal fields.
  // Option labels below must match Folk exactly, including the
  // "WIthin" capitalisation.
  if (fields['Are you prepared to invest USD $2k into this?'] === 'No') {
    put('Status', 'Closed-lost');
    put('Time of withdrawal', 'WIthin application');
    put('Reason for withdrawal', ['Unwilling to pay at all']);
  }

  const used = new Set();
  const blocks = [];

  for (const section of SECTIONS) {
    const rows = [];
    for (const label of section.fields) {
      const key = Object.keys(answers).find(k => norm(k) === norm(label));
      if (!key) continue;
      used.add(key);
      rows.push('**' + key + '**', '', answers[key], '');
    }
    if (rows.length) blocks.push('## ' + section.title, '', ...rows);
  }

  const leftovers = Object.keys(answers).filter(k => !used.has(k));
  if (leftovers.length) {
    blocks.push('## Other', '');
    for (const k of leftovers) blocks.push('**' + k + '**', '', answers[k], '');
  }

  const submitted = String(item.json.submissionTime || '').slice(0, 10);
  const header = ['# Application - ' + submitted, ''];
  if (branch) header.push('**Track:** ' + branch, '');
  header.push('**Fillout ID:** ' + (item.json.submissionId || 'unknown'), '');
  const noteContent = header.concat(blocks).join('\n');

  const person = (cf) => ({
    firstName: first.value,
    lastName: last.value,
    emails: mail.value ? [mail.value] : [],
    phones: tel.value ? [tel.value] : [],
    customFieldValues: { [FOLK_GROUP_ID]: cf },
  });

  out.push({
    json: {
      email: mail.value,
      submissionId: item.json.submissionId,
      branch: branch,
      noteContent: noteContent,
      createBody: Object.assign({}, person(fields), { groups: [{ id: FOLK_GROUP_ID }] }),
      updateBody: ADD_GROUP_ON_UPDATE
        ? Object.assign({}, person(fields), { groups: [{ id: FOLK_GROUP_ID }] })
        : person(fields),
      _fields: Object.keys(fields).sort(),
      _warnings: warnings,
    },
  });
}

return out;

// ================================================================
//  AI APPLICATION REVIEW - request builder
//
//  Everything worth editing lives in this block: the model, how many
//  web searches one review may run, and the wording of the brief.
//  The next node just posts the object this builds to Anthropic.
//
//  Three things to keep if you rewrite the prompt:
//   1. The <review> tags. Extract AI Review uses them to throw away
//      the model's search narration. Drop them and that filler ends
//      up in the Folk note.
//   2. MAX_TOKENS headroom. It covers the model's reasoning as well as
//      the visible answer. At 2500 reviews were cut off mid-sentence.
//      Check _stopReason on Extract AI Review: 'end_turn' means it
//      finished, 'max_tokens' means raise this.
//   3. The <two_k_answer> tag. Build Folk Payload already resolves the
//      $2k question to a clean Yes or No, so the model must never work
//      it out from the note. It got this wrong in Aug 2026 on a Grow
//      applicant, where the $2k item is worded as a statement about DQ
//      pricing rather than a question, and reported a Yes as a No.
// ================================================================

const MODEL        = 'claude-sonnet-5';
const MAX_TOKENS   = 6000;
const MAX_SEARCHES = 6;

// The Folk field Build Folk Payload writes the resolved answer to.
const TWO_K_FIELD = 'Are you prepared to invest USD $2k into this?';

const SYSTEM = [
  'You screen inbound applications for DQventures, an early-stage venture builder that works with experienced professionals across London, Singapore and Sydney.',
  '',
  'There are three programmes. Pick exactly one:',
  '- DQ Grow: they already run a business and want help growing it.',
  '- DQ Explore: they have one specific business idea they want to test.',
  '- DQ Ideate: they have no idea, or several ideas and no way to choose between them.',
  '',
  'OUTPUT FORMAT. Wrap the finished review in <review> and </review> tags. Between those tags put nothing but the review itself, starting with the heading "## Recommended programme" and ending with the Worth an interview line. Never open the tags until you have finished searching and are ready to write the whole thing in one go. Anything you need to say while working - what you are about to search for, what you found, that you have enough to start - goes before the opening tag, never inside. Always close the tags.',
  '',
  'CALIBRATE FOR STAGE. Almost everyone who applies is pre-launch and pre-revenue. Doing the validation work with them is the whole point of DQventures. The following are normal at this stage and must never be written up as weaknesses, concerns, or reasons a partner would hesitate:',
  '- no customers, no revenue, no product, no MVP',
  '- no financial model, no pricing, no plan for what the money goes on',
  '- no names or proof behind a claim that people in their network would buy',
  '- a broad or unscoped idea, or a market they have not narrowed yet',
  '- a crowded competitive space, which is true of most good ideas',
  '- not having worked out positioning, differentiation or a wedge',
  '',
  'What IS worth flagging:',
  '- an application answered in a few words with no thought behind it',
  '- written English weak enough to be a problem on client calls',
  '- someone who reads as a tyre-kicker, a student exercise, or an agency touting for work',
  '- someone who wants a job, a co-founder, or free advice rather than to build something',
  '- something OTHER THAN the $2k answer itself suggesting they cannot or will not spend the $2k, for example asking DQ for funding or investment',
  '- a clear mismatch between what they are asking for and what DQ does',
  '',
  'THE $2k ANSWER. This one is given to you, not for you to work out. You will be handed it in a <two_k_answer> tag, resolved from the form data. That tag is the only source you may use for it.',
  '- Never read, infer, quote or reason about the $2k answer from the application text. The wording in the application varies by track and is easy to misread. Ignore it entirely.',
  '- If <two_k_answer> says Yes, or says Not asked, do not mention the $2k anywhere in the review at all. Not in Fit, not in the Worth an interview line, nowhere. A Yes tells a partner nothing.',
  '- If <two_k_answer> says No, write exactly one line in the Fit section saying they answered No to the $2k, then move on.',
  '',
  'One more thing never to write inside the review:',
  '- Do not mention, compare against, or endorse the track the applicant picked for themselves on the form. Just give your recommendation.',
  '',
  'How to write:',
  '- Judge on the evidence in the application and on what you find by searching the web. Never invent facts.',
  '- Plain English, short sentences, no buzzwords, no flattery.',
  '- Everything in your own words. Never paste sentences out of search results.',
  '- Where you are unsure, say so in a few words.',
  '- Keep the review under 450 words. A partner should read it in a minute.',
  '- You are writing for one reader: the DQ partner deciding whether to interview this person.',
].join('\n');

const BRIEF = [
  'Search first, then write the review in one pass inside <review> tags, using exactly the sections below.',
  '',
  '## Recommended programme',
  'DQ Grow, DQ Explore or DQ Ideate, then one or two sentences on why.',
  '',
  '## Revenue',
  'Include this section only if you recommended DQ Grow. Otherwise leave it out completely.',
  'A short list, numbers taken straight from the application: revenue last month, lifetime revenue, revenue model, paying customers last month, customers who paid more than once, how they won those customers. Write "not answered" against anything missing.',
  '',
  '## The business',
  'Three to five sentences on what the business or idea actually is: who it serves, what it sells, how it makes money. Where the application does not tell you, say so plainly and move on. Do not treat a gap as a fault.',
  'If you recommended DQ Ideate, use this section instead for what is useful about them: background, sectors they lean towards, constraints, any half-formed ideas.',
  '',
  '## Competitors',
  'Leave this section out completely if you recommended DQ Ideate.',
  'Otherwise use the searches you already ran. Three to five real companies doing something close, weighted towards the country and market the applicant is in where that matters.',
  'One or two lines each, in your own words: what they do, how they differ from this applicant, and how established they are (funding, stage, age or headcount, whatever you can actually find). If you cannot find funding or size for one, say so in three words rather than padding.',
  'Then two or three sentences on where an opening might be for this applicant. Frame it as where to aim, not as a problem with their idea.',
  'If you could not find real companies, say so plainly instead of guessing.',
  '',
  '## Fit',
  'Under 120 words on whether this is a good DQventures applicant. Only the things listed as worth flagging. If nothing is worth flagging, say the application is solid and keep it to a line or two.',
  'Mention the $2k only if <two_k_answer> says No, and then only in the one line described above.',
  'Finish with one line: "Worth an interview: yes / no / borderline", plus half a sentence of reason. Then close the tag.',
].join('\n');

// ----------------------------------------------------------------
//  Below here: no configuration.
// ----------------------------------------------------------------

// Build Folk Payload nests the resolved custom fields under the Folk
// group id. Read the first (only) group rather than hardcoding the id,
// so changing groups cannot silently blank this out.
const readTwoK = (j) => {
  const cfMap = (j.createBody || {}).customFieldValues || {};
  const cf = Object.values(cfMap)[0] || {};
  const raw = String(cf[TWO_K_FIELD] == null ? '' : cf[TWO_K_FIELD]).trim();
  return raw || 'Not asked';
};

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const twoK = readTwoK(j);

  const userText = [
    'Here is the application, exactly as submitted.',
    '',
    '<application>',
    j.noteContent || '(no application content)',
    '</application>',
    '',
    'Here is the applicant\'s answer to the $2k question, resolved from the form data. Treat it as fact. Do not check it against the application text or override it with your own reading.',
    '',
    '<two_k_answer>' + twoK + '</two_k_answer>',
    '',
    BRIEF,
  ].join('\n');

  out.push({
    json: Object.assign({}, j, {
      aiModel: MODEL,
      _twoKAnswer: twoK,
      aiBody: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: SYSTEM,
        tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: MAX_SEARCHES }],
        messages: [{ role: 'user', content: userText }],
      },
    }),
    pairedItem: { item: i },
  });
}

return out;

// Pulls the review out of the Anthropic response.
//
// The model is told to wrap the review in <review> tags. Anything it
// says while working - narrating searches, "now I have enough" - lives
// outside those tags and gets thrown away. Position does not matter, so
// it does not care what order the model searches and writes in.
//
// Four ways out, in order of preference. _reviewSource records which
// one was used. If you ever see anything other than 'tags', the model
// stopped closing its tags and the prompt needs a look.
//   tags            both tags present. Normal.
//   tags-truncated  opening tag only - it ran out of tokens mid-review.
//   heading         no tags, cut from the first ## heading instead.
//   all-text        no tags and no headings. Raw. Expect narration.
//
// The HTTP node before this carries on if the API call fails, so a bad
// review never costs us the Folk note - we write a placeholder instead.
//
// Also worth checking after a run:
//   _reviewOk     false means the review is a placeholder
//   _stopReason   'max_tokens' means raise MAX_TOKENS upstream
//   _usage        token spend, including web search

const OPEN  = '<review>';
const CLOSE = '</review>';

function pickReview(blocks) {
  const all = blocks
    .filter((b) => b && b.type === 'text' && b.text)
    .map((b) => b.text)
    .join('\n');

  const open  = all.indexOf(OPEN);
  const close = all.lastIndexOf(CLOSE);

  if (open !== -1 && close > open) {
    return { text: all.slice(open + OPEN.length, close), source: 'tags' };
  }
  if (open !== -1) {
    return { text: all.slice(open + OPEN.length), source: 'tags-truncated' };
  }

  const heading = all.indexOf('## ');
  if (heading !== -1) {
    return { text: all.slice(heading), source: 'heading' };
  }

  return { text: all, source: 'all-text' };
}

const items   = $input.all();
const sources = $('Build AI Review Request').all();
const out     = [];

for (let i = 0; i < items.length; i++) {
  const res    = items[i].json || {};
  const blocks = Array.isArray(res.content) ? res.content : [];

  const picked = pickReview(blocks);

  // Belt and braces: no stray tag fragments reach Folk.
  const text = picked.text.split(OPEN).join('').split(CLOSE).join('').trim();

  let failure = '';
  if (!text) {
    failure = res.error
      ? (typeof res.error === 'string' ? res.error : JSON.stringify(res.error))
      : 'empty response from Anthropic';
  }

  const review = text
    ? ['# AI review', '', text, '', '_Written by Claude from the application below, using web search. Competitor detail is a starting point, not fact-checked._'].join('\n')
    : ['# AI review', '', '_Not available for this submission: ' + failure + '_'].join('\n');

  const base = Object.assign({}, (sources[i] && sources[i].json) || {});
  delete base.aiBody;
  base.review        = review;
  base._reviewOk     = Boolean(text);
  base._reviewSource = picked.source;
  base._reviewError  = failure;
  base._stopReason   = res.stop_reason || null;
  base._usage        = res.usage || null;

  out.push({ json: base, pairedItem: { item: i } });
}

return out;
